class Solution {
    public double[] runningMedian(int[] nums) {
        List<Integer> seen = new ArrayList<>();
        double[] out = new double[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int pos = Collections.binarySearch(seen, nums[i]);
            seen.add(pos < 0 ? -pos - 1 : pos, nums[i]);
            int k = seen.size();
            out[i] = k % 2 == 1 ? seen.get(k / 2) : ((double) seen.get(k / 2 - 1) + seen.get(k / 2)) / 2.0;
        }
        return out;
    }
}

