import "container/heap"

type medianHeap struct {
    a    []int
    less func(x, y int) bool
}

func (h *medianHeap) Len() int           { return len(h.a) }
func (h *medianHeap) Less(i, j int) bool { return h.less(h.a[i], h.a[j]) }
func (h *medianHeap) Swap(i, j int)      { h.a[i], h.a[j] = h.a[j], h.a[i] }
func (h *medianHeap) Push(x any)         { h.a = append(h.a, x.(int)) }
func (h *medianHeap) Pop() any {
    x := h.a[len(h.a)-1]
    h.a = h.a[:len(h.a)-1]
    return x
}

func runningMedian(nums []int) []float64 {
    low := &medianHeap{less: func(x, y int) bool { return x > y }}
    high := &medianHeap{less: func(x, y int) bool { return x < y }}
    out := make([]float64, 0, len(nums))
    for _, x := range nums {
        heap.Push(low, x)
        heap.Push(high, heap.Pop(low))
        if high.Len() > low.Len() {
            heap.Push(low, heap.Pop(high))
        }
        if low.Len() > high.Len() {
            out = append(out, float64(low.a[0]))
        } else {
            out = append(out, (float64(low.a[0])+float64(high.a[0]))/2)
        }
    }
    return out
