import java.util.*;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        List<Integer> window = new ArrayList<>();
        for (int i = 0; i < k; i++) window.add(nums[i]);
        Collections.sort(window);
        double[] out = new double[nums.length - k + 1];
        for (int i = k; ; i++) {
            out[i - k] = k % 2 == 1 ? window.get(k / 2) : ((double) window.get(k / 2 - 1) + window.get(k / 2)) / 2.0;
            if (i == nums.length) break;
            window.remove(Collections.binarySearch(window, nums[i - k]));
            int pos = Collections.binarySearch(window, nums[i]);
            window.add(pos < 0 ? -pos - 1 : pos, nums[i]);
        }
        return out;
    }
}

