        pos := sort.SearchInts(window, nums[i-k])
        window = append(window[:pos], window[pos+1:]...)
        pos = sort.SearchInts(window, nums[i])
        window = append(window, 0)
        copy(window[pos+1:], window[pos:])
        window[pos] = nums[i]
    }
    return out
